const ANALYZER_DATA = window.ANALYZER_DATA;
let currentAnalyzerCommodity = "GOLD";
let analyzerActiveIndex = -1;

function onAnalyzerSearchInput(val) {
    const text = (val || "").trim().toUpperCase();
    const sugBox = document.getElementById("analyzerSuggestions");
    if (!sugBox) return;

    if (!text || text.length < 1) {
        sugBox.style.display = "none";
        return;
    }

    const matches = [];
    const symbols = Object.keys(ANALYZER_DATA);
    for (let i = 0; i < symbols.length; i++) {
        const sym = symbols[i];
        const item = ANALYZER_DATA[sym];
        const name = (item.company_name || "").toUpperCase();
        if (sym === text) {
            matches.unshift({ sym: sym, name: item.company_name, item: item });
        } else if (sym.startsWith(text)) {
            matches.push({ sym: sym, name: item.company_name, item: item });
        } else if (sym.includes(text) || name.includes(text)) {
            matches.push({ sym: sym, name: item.company_name, item: item });
        }
        if (matches.length >= 10) break;
    }

    if (matches.length === 0) {
        sugBox.innerHTML = '<div style="padding:10px; color:#888; font-size:12px;">No matching NSE stock found</div>';
        sugBox.style.display = "block";
        return;
    }

    let html = "";
    matches.slice(0, 10).forEach(m => {
        const isFno = !!m.item.fno;
        const tag = isFno
            ? '<span style="font-size:10px; background:#dcfce7; color:#15803d; padding:2px 6px; border-radius:4px; font-weight:700;">F&O</span>'
            : '<span style="font-size:10px; background:#f1f5f9; color:#475569; padding:2px 6px; border-radius:4px; font-weight:700;">CASH</span>';

        html += '<div class="analyzer-suggestion-item" data-sym="' + m.sym + '" onclick="selectAnalyzerCommodity(this.dataset.sym)">' +
            '<div><strong>' + m.sym + '</strong> <span style="font-size:11px; color:#64748b; margin-left:6px;">' + m.name + '</span></div>' +
            '<div>' + tag + '</div>' +
            '</div>';
    });

    sugBox.innerHTML = html;
    sugBox.style.display = "block";
    analyzerActiveIndex = -1;
}

function onAnalyzerSearchKeyDown(e) {
    const sugBox = document.getElementById("analyzerSuggestions");
    if (!sugBox || sugBox.style.display === "none") {
        if (e.key === "Enter") triggerAnalyzerSearch();
        return;
    }

    const items = sugBox.querySelectorAll(".analyzer-suggestion-item");
    if (e.key === "ArrowDown") {
        e.preventDefault();
        analyzerActiveIndex = (analyzerActiveIndex + 1) % items.length;
        updateSuggestionHighlight(items);
    } else if (e.key === "ArrowUp") {
        e.preventDefault();
        analyzerActiveIndex = (analyzerActiveIndex - 1 + items.length) % items.length;
        updateSuggestionHighlight(items);
    } else if (e.key === "Enter") {
        e.preventDefault();
        if (analyzerActiveIndex >= 0 && items[analyzerActiveIndex]) {
            items[analyzerActiveIndex].click();
        } else {
            triggerAnalyzerSearch();
        }
    } else if (e.key === "Escape") {
        sugBox.style.display = "none";
    }
}

function updateSuggestionHighlight(items) {
    items.forEach((it, idx) => {
        if (idx === analyzerActiveIndex) it.classList.add("active");
        else it.classList.remove("active");
    });
}

function triggerAnalyzerSearch() {
    const input = document.getElementById("analyzerInput");
    if (!input) return;
    const query = input.value.trim().toUpperCase();
    if (!query) return;

    if (ANALYZER_DATA[query]) {
        selectAnalyzerCommodity(query);
        return;
    }

    const symbols = Object.keys(ANALYZER_DATA);
    for (let i = 0; i < symbols.length; i++) {
        const sym = symbols[i];
        const item = ANALYZER_DATA[sym];
        const name = (item.company_name || "").toUpperCase();
        if (sym === query || sym.includes(query) || name.includes(query)) {
            selectAnalyzerCommodity(sym);
            return;
        }
    }

    alert("Share '" + query + "' not found in MCX universe.");
}

function selectAnalyzerCommodity(symbol) {
    const sugBox = document.getElementById("analyzerSuggestions");
    if (sugBox) sugBox.style.display = "none";

    const input = document.getElementById("analyzerInput");
    if (input) input.value = symbol;

    const sym = (symbol || "").trim().toUpperCase();
    const d = ANALYZER_DATA[sym];
    const dossierDiv = document.getElementById("analyzerDossier");
    if (!dossierDiv) return;

    if (!d) {
        dossierDiv.innerHTML = '<div style="padding:40px; text-align:center; color:#888;">Stock ' + sym + ' not found in universe.</div>';
        return;
    }

    currentAnalyzerCommodity = sym;
    dossierDiv.innerHTML = renderFullDossierHtml(d);
}

