function renderScoreBar(label, val, col) {
    return '<div class="analyzer-score-bar-wrap">' +
        '<div class="analyzer-score-bar-header">' +
          '<span>' + label + '</span>' +
          '<span style="color:' + col + ';">' + val + ' / 100</span>' +
        '</div>' +
        '<div class="analyzer-score-bar-track">' +
          '<div class="analyzer-score-bar-fill" style="width:' + Math.min(100, Math.max(0, val)) + '%; background:' + col + ';"></div>' +
        '</div>' +
      '</div>';
}

function computeUnifiedVerdict(fno, score, quant) {
    let scoreTotal = 50;
    let bullishFactors = [];
    let bearishFactors = [];
    let warnings = [];

    if (fno && fno.signal) {
        const sig = (fno.signal || "").toUpperCase();
        if (sig === "LONG") {
            scoreTotal += 20;
            bullishFactors.push("F&O Derivatives Flow: Active LONG build-up indicates institutional buying posture.");
        } else if (sig === "COVER") {
            scoreTotal += 12;
            bullishFactors.push("F&O Derivatives Flow: Short covering posture supports upside recovery.");
        } else if (sig === "SHORT") {
            scoreTotal -= 20;
            bearishFactors.push("F&O Derivatives Flow: Active SHORT build-up shows aggressive call writing / sell-side pressure.");
        } else if (sig === "UNWIND") {
            scoreTotal -= 12;
            bearishFactors.push("F&O Derivatives Flow: Long unwinding indicates profit booking and loss of momentum.");
        }
        if (fno.final_score && fno.final_score >= 65) {
            scoreTotal += 8;
            bullishFactors.push("High conviction composite score (" + fno.final_score + "/100).");
        }
    } else {
        warnings.push("Cash Equity Stock: Evaluated via fundamental score and quantitative valuation models (No F&O derivatives data).");
    }

    if (score && score.total_score !== null && score.total_score !== undefined) {
        const tot = score.total_score;
        if (tot >= 7.0) {
            scoreTotal += 15;
            bullishFactors.push("Top Decile MC Score (" + Number(tot).toFixed(1) + "/10 percentile) reflects strong bullish OI buildup.");
        } else if (tot >= 5.0) {
            scoreTotal += 6;
            bullishFactors.push("Moderate MC Score (" + Number(tot).toFixed(1) + "/10 percentile) confirms neutral market positioning.");
        } else {
            scoreTotal -= 15;
            bearishFactors.push("Low MC Score (" + Number(tot).toFixed(1) + "/10) warns of bearish OI buildup or short pressure.");
        }

        if (score.q_score && score.q_score >= 70) {
            bullishFactors.push("Quality Score (" + Math.round(score.q_score) + "/100) indicates exceptional financial health.");
        }
        if (score.g_score && score.g_score >= 70) {
            bullishFactors.push("Growth Score (" + Math.round(score.g_score) + "/100) confirms rapid revenue and profit expansion.");
        }
        if (score.v_score && score.v_score < 40) {
            bearishFactors.push("Value Score (" + Math.round(score.v_score) + "/100) signals rich valuation multiple relative to peers.");
        }
    }

    if (quant && quant.intraday_signal) {
        const qSig = quant.intraday_signal.toUpperCase();
        if (qSig.includes("BUY")) {
            scoreTotal += 15;
            bullishFactors.push("AI Quant Model: Bullish intraday stance with " + (quant.intraday_conf ? quant.intraday_conf.toFixed(1) : "") + "% model confidence.");
        } else if (qSig.includes("SELL")) {
            scoreTotal -= 15;
            bearishFactors.push("AI Quant Model: Bearish intraday stance with " + (quant.intraday_conf ? quant.intraday_conf.toFixed(1) : "") + "% model confidence.");
        }
    }

    scoreTotal = Math.max(5, Math.min(95, scoreTotal));

    let stanceLabel, stanceColor, stanceBg, strategyText;
    if (scoreTotal >= 70) {
        stanceLabel = "STRONG CONVICTION BUY (BULLISH CONFLUENCE)";
        stanceColor = "#15803d";
        stanceBg = "#dcfce7";
        strategyText = "OI buildup, commodity momentum, and quant projections are positively aligned. Recommended for momentum long or swing positions with trailing stops.";
    } else if (scoreTotal >= 55) {
        stanceLabel = "SELECTIVE ACCUMULATION (MILDLY BULLISH)";
        stanceColor = "#1d4ed8";
        stanceBg = "#eff6ff";
        strategyText = "Positive overall setup with constructive indicators. Accumulate on pullbacks near support/pivot levels.";
    } else if (scoreTotal >= 45) {
        stanceLabel = "NEUTRAL / RANGE-BOUND (WATCHLIST)";
        stanceColor = "#b45309";
        stanceBg = "#fef3c7";
        strategyText = "Mixed signals across derivatives flow and valuation. Wait for a decisive breakout above resistance or dip to key support.";
    } else if (scoreTotal >= 30) {
        stanceLabel = "BEARISH BIAS / SHORT ON BOUNCES";
        stanceColor = "#b91c1c";
        stanceBg = "#fee2e2";
        strategyText = "Sell-side pressure dominant. Avoid fresh aggressive longs; consider hedging or shorting on intraday rallies near pivot.";
    } else {
        stanceLabel = "HIGH RISK / STRONG BEARISH PRESSURE";
        stanceColor = "#7f1d1d";
        stanceBg = "#fecaca";
        strategyText = "Strong negative confluence across derivatives, technicals, or valuation. Exercise strict caution or stay aside.";
    }

    return {
        score: scoreTotal,
        label: stanceLabel,
        color: stanceColor,
        bg: stanceBg,
        strategy: strategyText,
        bullish: bullishFactors,
        bearish: bearishFactors,
        warnings: warnings
    };
}

function initAnalyzerDefault() {
    const dossierDiv = document.getElementById("analyzerDossier");
    if (dossierDiv && (!dossierDiv.innerHTML.trim() || currentAnalyzerCommodity === "GOLD")) {
        selectAnalyzerCommodity("GOLD");
    }
}

window.initAnalyzerTab = function() {
    initAnalyzerDefault();
};

document.addEventListener("click", function(e) {
    const sugBox = document.getElementById("analyzerSuggestions");
    const input = document.getElementById("analyzerInput");
    if (sugBox && e.target !== input && !sugBox.contains(e.target)) {
        sugBox.style.display = "none";
    }
});

// Explicit window bindings for inline HTML event handlers & tab loader
window.ANALYZER_DATA = typeof ANALYZER_DATA !== 'undefined' ? ANALYZER_DATA : {};
window.onAnalyzerSearchInput = onAnalyzerSearchInput;
window.onAnalyzerSearchKeyDown = onAnalyzerSearchKeyDown;
window.triggerAnalyzerSearch = triggerAnalyzerSearch;
window.selectAnalyzerCommodity = selectAnalyzerCommodity;
window.initAnalyzerDefault = initAnalyzerDefault;
window.initAnalyzerTab = initAnalyzerDefault;

// Initialize immediately if in DOM
if (document.getElementById("analyzerDossier")) {
    initAnalyzerDefault();
}